import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('exportCsv returns header for empty array', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv exports single issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[2], '');
});

test('exportCsv includes invoice number in CSV', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].startsWith('INV-2026-0001,'), true);
});

test('exportCsv includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('Silver Inc'), true);
});

test('exportCsv formats amounts in euros with 2 decimals', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '425.00');
});

test('exportCsv uses dot as decimal separator', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  assert.equal(result.includes('.'), true);
  assert.equal(result.includes(','), true);
});

test('exportCsv exports multiple invoices in order', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(invoice2, ['INV-2026-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');
  assert.equal(lines[1].startsWith('INV-2026-0001'), true);
  assert.equal(lines[2].startsWith('INV-2026-0002'), true);
});

test('exportCsv escapes fields with commas', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    number: 'INV-001,TEST',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 2.5 }],
  };

  const result = exportCsv([invoice]);
  assert.equal(result.includes('"INV-001,TEST"'), true);
});

test('exportCsv escapes fields with double quotes', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    number: 'INV-"001',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 2.5 }],
  };

  const result = exportCsv([invoice]);
  assert.equal(result.includes('"INV-""001"'), true);
});

test('exportCsv doubles double quotes in field values', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    number: 'INV-001"TEST"',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 2.5 }],
  };

  const result = exportCsv([invoice]);
  assert.equal(result.includes('"INV-001""TEST"""'), true);
});

test('exportCsv handles lines ending with newline', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[0].includes('\n'), false);
  assert.equal(lines[1].includes('\n'), false);
});

test('exportCsv includes all columns in correct order', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const headers = lines[0].split(',');
  assert.deepEqual(headers, [
    'number',
    'customer',
    'issueDate',
    'dueDate',
    'status',
    'subtotal',
    'discount',
    'vat',
    'total',
    'due',
  ]);
});

test('exportCsv exports draft invoices without number', () => {
  const draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = exportCsv([draft]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[0], '');
});

test('exportCsv includes issue date', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('2026-10-07'), true);
});

test('exportCsv includes due date', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('2026-11-06'), true);
});

test('exportCsv includes invoice status', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('issued'), true);
});

test('exportCsv calculates subtotal correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '425.00');
});

test('exportCsv calculates discount correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[6], '10.62');
});

test('exportCsv calculates VAT correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[7], '87.02');
});

test('exportCsv calculates total correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[8], '501.40');
});

test('exportCsv sets due equal to total', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[8], fields[9]);
});

test('exportCsv handles zero amounts', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'draft',
    lines: [],
  };

  const result = exportCsv([invoice]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('0.00'), true);
});

test('exportCsv exports partially_paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const partiallyPaid = { ...issued, status: 'partially_paid' };

  const result = exportCsv([partiallyPaid]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('partially_paid'), true);
});

test('exportCsv exports paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const paid = { ...issued, status: 'paid' };

  const result = exportCsv([paid]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('paid'), true);
});

test('exportCsv handles negative values as zero', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'draft',
    lines: [],
  };

  const result = exportCsv([invoice]);
  assert.equal(result.includes('-'), false);
});

