  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 10 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('1200'), true);
  assert.equal(lines[1].includes('1,200'), false);
});

test('exportCsv with multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'PRINT-A4', qty: 5 },
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('Silver Inc'), true);
  assert.equal(lines[1].length > 0, true);
});

test('exportCsv handles customer names with special characters', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[1].includes('Silver Inc'), true);
});

test('exportCsv returns string ending with newline', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = exportCsv([issued]);
  assert.equal(result.endsWith('\n'), true);
});

test('exportCsv does not mutate input', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const invoices = [issued];
  const invoicesCopy = JSON.parse(JSON.stringify(invoices));

  exportCsv(invoices);
  assert.deepEqual(invoices, invoicesCopy);
});

