  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');
  assert.equal(lines[1].startsWith('INV-2026-0001'), true);
  assert.equal(lines[2].startsWith('INV-2026-0002'), true);
});

test('exportCsv escapes fields with commas', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
